const clean = s => String(s || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\s*[\(\[].*?[\)\]]/g, '')
  .replace(/[^a-z0-9 ]/g, '')
  .replace(/\s+/g, ' ').trim();
const lev = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++)
      d[i][j] = Math.min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + (a[i-1] === b[j-1] ? 0 : 1));
  return d[a.length][b.length];
};

const round = $input.first().json;
const text = $('Telegram Trigger').first().json.message.text || '';
const mode = round.mode || 'classic';
const song = `${round.title} – ${round.artist}`;
const skip = text.startsWith('/skip');

// 🕵️ WHO MODE
if (mode === 'who') {
  const g = clean(text), o = clean(round.owner);
  const sim = o.length && g.length ? 1 - lev(g, o) / Math.max(g.length, o.length) : 0;
  const ok = !skip && g.length >= 2 && (g === o || o.includes(g) || g.includes(o) || sim >= 0.75);
  return [{ json: { ...round, skip, mode, guess: g, similarity: 0, ok, points: 1, answer_text: `${round.owner}'s playlist 🎧 ${song}` } }];
}

// 📅 YEAR MODE
if (mode === 'year') {
  const m = text.match(/\b(19|20)\d{2}\b/);
  const guessYear = m ? Number(m[0]) : null;
  const year = Number(round.year);
  const diff = guessYear && year ? Math.abs(guessYear - year) : 99;
  const points = skip ? 0 : diff === 0 ? 3 : diff <= 2 ? 2 : diff <= 5 ? 1 : 0;
  return [{ json: { ...round, skip, mode, guess: guessYear, similarity: 0, ok: points > 0, points, answer_text: `${year} · ${song}` } }];
}

// 🎧 CLASSIC MODE
const guess = clean(text);
const answer = clean(round.answer);
const similarity = skip || !answer.length ? 0 : 1 - lev(guess, answer) / Math.max(guess.length, answer.length);
const exact = !skip && guess.length >= 3 && (guess === answer || answer.includes(guess) || guess.includes(answer));
const ok = exact || similarity >= 0.8;
return [{ json: { ...round, skip, mode, guess, similarity: Math.round(similarity * 100), ok, points: 1, answer_text: song } }];

const chat = String($('Telegram Trigger').first().json.message.chat.id);
const game = $('Read Game').all().filter(i => String(i.json.chat_id) === chat).pop();
const gameId = game ? String(game.json.game_id || '') : '';
const isStop = ($('Telegram Trigger').first().json.message.text || '').startsWith('/stop');

const counts = {};
for (const i of $input.all()) {
  if (String(i.json.chat_id) !== chat) continue;
  if (!gameId || String(i.json.game_id) !== gameId) continue;
  const u = i.json.user;
  if (u) counts[u] = (counts[u] || 0) + (Number(i.json.points) || 1);
}

const medals = ['🥇', '🥈', '🥉'];
const lines = Object.entries(counts)
  .sort((a, b) => b[1] - a[1])
  .map(([u, n], i) => `${medals[i] || '▫️'} ${u}: ${n} pt${n > 1 ? 's' : ''}`);

const title = isStop ? '🏁 Game over! Final scores' : '🏆 Scores for this game';
const text = lines.length
  ? `${title}\n\n${lines.join('\n')}`
  : (isStop ? '🏁 Game over! Nobody scored this time 😅' : 'No points yet in this game, keep guessing! 🎶');
return [{ json: { text } }];

