const raw = String($input.first().json.text || '');
const m = raw.match(/"correct"\s*:\s*(true|false)/i);
// if the AI fails or answers weirdly → count as wrong
return [{ json: { ok: m ? m[1].toLowerCase() === 'true' : false, ai_raw: raw } }];

const tg = $('Telegram Trigger').first().json.message;
const chat = String(tg.chat.id);
const text = tg.text || '';
const DEFAULT = '3MOKTx8faxQ1SXhfuu1Eho';
const MIN_PLAYERS = 2;   // set to 1 to test alone

// which mode?
let mode;
if (text.startsWith('/year')) mode = 'year';
else if (text.startsWith('/play')) mode = 'classic';
else if (text.startsWith('/who')) mode = 'who';
else mode = $('Check Guess').isExecuted ? ($('Check Guess').first().json.mode || 'classic') : 'classic';

// 🕵️ WHO MODE → random player's playlist
if (mode === 'who') {
  const players = $('Read Players').all().map(i => i.json)
    .filter(p => String(p.chat_id) === chat && p.playlist_id);
  if (players.length < MIN_PLAYERS) {
    return [{ json: { mode, error: `Need at least ${MIN_PLAYERS} players 🕵️ Each player sends /mine <spotify playlist link>` } }];
  }
  const p = players[Math.floor(Math.random() * players.length)];
  return [{ json: { mode, playlist_id: p.playlist_id, owner: p.user, error: '' } }];
}

// 🎧 / 📅 → this chat's playlist
const row = $('Read Settings').all().filter(i => String(i.json.chat_id) === chat).pop();
return [{ json: { mode, playlist_id: (row && row.json.playlist_id) || DEFAULT, owner: '', error: '' } }];

